  setFollowedAuthors(Object.fromEntries((followsRes.data||[]).map(r=>[r.followed_id,true])));const blocked=Object.fromEntries((blocksRes.data||[]).map(r=>[r.blocked_id,true]));setBlockedAuthors(blocked);
  const likeCounts=new Map(),replyCounts=new Map();for(const reaction of reactionRows)likeCounts.set(reaction.post_id,(likeCounts.get(reaction.post_id)||0)+1);for(const reply of replyRows)replyCounts.set(reply.post_id,(replyCounts.get(reply.post_id)||0)+1);setPosts(rows.filter(p=>!blocked[p.author_id]).map(p=>({...p,profile:profileMap[p.author_id]||{},likes:likeCounts.get(p.id)||0,replies:replyCounts.get(p.id)||0})));
